import React from 'react';
import { DataTable, Table, TableHead, TableRow, TableHeader, TableBody, TableCell, Tag } from 'carbon-components-react';

const rows = [
  { id: 'a', name: 'Load balancer 1', status: 'Disabled' },
  { id: 'b', name: 'Load balancer 2', status: 'Starting' },
  { id: 'c', name: 'Load balancer 3', status: 'Active' },
];

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

const ShortTag = () => (
  <Tag type="gray" size="sm">Gray tag</Tag>
);

const DataTableExample = () => (
  <DataTable rows={rows} headers={headers}>
    {({ rows, headers, getTableProps, getHeaderProps, getRowProps }) => (
      <Table {...getTableProps()}>
        <TableHead>
          <TableRow>
            {headers.map((header) => (
              <TableHeader {...getHeaderProps({ header })}>
                {header.header}
              </TableHeader>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {rows.map((row) => (
            <TableRow {...getRowProps({ row })}>
              {row.cells.map((cell) => (
                <TableCell key={cell.id}>{cell.value}</TableCell>
              ))}
              <TableCell><ShortTag /></TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    )}
  </DataTable>
);

export default DataTableExample;
